import{_ as l,C as s,o as n,c as e,j as i,E as d,a as r,a2 as o}from"./chunks/framework.C21TwvGF.js";const D=JSON.parse(`{"title":"4-hafta (Mentor)","description":"","frontmatter":{"title":"4-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"n":4,"bob":"II-bob · Elektronika va Arduino bilan interaktiv interfeyslar","lessons":[{"g":10,"title":"10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi","lead":"Fonarni bir bosishda yoqasiz, ikkinchi bosishda u miltillay boshlaydi, uchinchisida tez miltillaydi. Bitta tugma — bir nechta rejim. Bugun shunday «aqlli» boshqaruv dasturini yozamiz.","link":"/mentor/9-sinf-iot/hafta-04/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-1-test.html"},{"g":11,"title":"11-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (1-qism)","lead":"Uydagi chiroq kalitini bosganingizda nima sodir bo'ladi? Siz shunchaki elektr zanjirini yopasiz yoki ochasiz. Bugun dasturisiz, faqat breadboard, DIP switch va LED bilan shunday zanjirni o'zimiz yig'amiz.","link":"/mentor/9-sinf-iot/hafta-04/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-2-test.html"},{"g":12,"title":"12-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (2-qism)","lead":"Sanoat pressi ishchi ikkala qo'li bilan ikki tugmani bosgandagina ishlaydi, avtobusdagi «to'xtash» chirog'i esa istalgan tugmadan yonadi. Bu «VA» va «YOKI» mantig'i — bugun uni ikki kalit bilan yig'amiz va DIP switch'ni Arduino'ga ulaymiz.","link":"/mentor/9-sinf-iot/hafta-04/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-04/index.md","filePath":"mentor/9-sinf-iot/hafta-04/index.md"}`),h={name:"mentor/9-sinf-iot/hafta-04/index.md"},m={class:"blk"},c={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},b={id:"baholash-mezoni",tabindex:"-1"};function g(q,a,k,v,y,z){const t=s("Icon");return n(),e("div",null,[i("div",m,[i("h2",c,[d(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan. Natijani Tinkercad havolasi yoki skrinshotlar bilan topshiring.</p><hr><h2 id="_10-dars-arduino-uno-va-tugma-orqali-led-holatini-boshqarish-dasturi" tabindex="-1">10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi <a class="header-anchor" href="#_10-dars-arduino-uno-va-tugma-orqali-led-holatini-boshqarish-dasturi" aria-label="Permalink to &quot;10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi&quot;">​</a></h2><ol><li>Tinkercad&#39;da Arduino UNO, tugma (Pin 2 → GND) va LED (Pin 9 → 220 Om → GND) sxemasini yig&#39;ing.</li><li><code>delay()</code> ishlatmasdan, <code>millis()</code> asosida 4 rejimli chiroq dasturini yozing: O&#39;CHIQ → YONIQ → SEKIN (500 ms) → TEZ (100 ms) → O&#39;CHIQ.</li><li>Rejim o&#39;zgarganda Serial Monitor&#39;ga <code>Rejim: SEKIN</code> kabi yozuv chiqsin (faqat o&#39;zgarganda).</li><li>Qo&#39;shimcha: Pin 13 ga heartbeat LED qo&#39;shing (700 ms) va u rejimlardan qat&#39;i nazar bir tekis miltillashini ko&#39;rsating.</li></ol><hr><h2 id="_11-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-1-qism" tabindex="-1">11-dars: DIP switch (DPST) va LED — oddiy elektron sikl (1-qism) <a class="header-anchor" href="#_11-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-1-qism" aria-label="Permalink to &quot;11-dars: DIP switch (DPST) va LED — oddiy elektron sikl (1-qism)&quot;">​</a></h2><ol><li>Tinkercad&#39;da 5 V manba, Breadboard, DIP Switch DPST, qizil va yashil LED dan zanjir yig&#39;ing: 1-kontakt Qizil LEDni, 2-kontakt Yashil LEDni mustaqil boshqarsin.</li><li>Har bir LED uchun rezistorni Om qonuni bo&#39;yicha hisoblang (qizil 2 V, yashil 3 V, tok 10 mA) va standart qiymatni tanlang.</li><li>4 ta holat (OFF/OFF, ON/OFF, OFF/ON, ON/ON) jadvalini tuzing va har biriga skrinshot qo&#39;shing.</li><li>Agar manba 9 V bo&#39;lsa, rezistorlar qanday o&#39;zgarishi kerakligini hisob bilan yozing.</li></ol><hr><h2 id="_12-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-2-qism" tabindex="-1">12-dars: DIP switch (DPST) va LED — oddiy elektron sikl (2-qism) <a class="header-anchor" href="#_12-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-2-qism" aria-label="Permalink to &quot;12-dars: DIP switch (DPST) va LED — oddiy elektron sikl (2-qism)&quot;">​</a></h2><ol><li>AND (ketma-ket) va OR (parallel) zanjirlarini yig&#39;ing; har biri uchun haqiqat jadvalini skrinshotlar bilan tasdiqlang.</li><li>Multimetr bilan 220, 330 va 1000 Om rezistorlarda tokni o&#39;lchab, jadval va xulosa yozing.</li><li>DIP switch&#39;ni Arduino&#39;ga ulang (DIP1 → Pin 2, DIP2 → Pin 3, qarama-qarshi oyoqlar GND) va 2 bitli kod bo&#39;yicha 4 rejimli tanlagichni dasturlang: 0 — o&#39;chiq, 1 — Yashil, 2 — Qizil, 3 — navbat bilan miltillash.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>10-dars vazifasi (35 ball):</strong> <code>millis()</code> andozasi to&#39;g&#39;ri (<code>unsigned long</code>, <code>oxirgi = millis()</code>), <code>% 4</code> bilan rejim aylanishi, <code>switch/case</code>, debounce (50 ms so&#39;rov), Serial&#39;ga faqat o&#39;zgarishda yozish.</li><li><strong>11-dars vazifasi (30 ball):</strong> komponentlar turli qatorlarda, DIP ariqcha ustida, LED qutbi to&#39;g&#39;ri, rezistor hisoblari (qizil — 330 Om, yashil — 220 Om; 9 V uchun 470–680 Om) asoslangan, 4 holat jadvali.</li><li><strong>12-dars vazifasi (35 ball):</strong> AND va OR sxemalari va jadvallari, multimetr to&#39;g&#39;ri ulangan (tok — ketma-ket), rezistor xulosasi, <code>INPUT_PULLUP</code> va <code>== LOW ? 1 : 0</code> bilan kod hisoblash, 4 rejim ishlashi.</li></ul><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>12-dars Arduino topshirig&#39;ida DIP switch tugmadan farqli ravishda holatini saqlashini, shuning uchun Toggle kerak emasligini o&#39;quvchi tushuntira olishini tekshiring.</li></ul>',17))]),i("div",u,[i("h2",b,[d(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Arduino UNO va tugma orqali LED holatini boshqarish dasturi: holat va hodisa, <code>#define</code>, <code>checkSwitch()</code>, <code>millis()</code>, heartbeat LED, 4 rejimli boshqaruv</li><li>Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (1-qism): zanjir qismlari, ochiq/yopiq zanjir, breadboard, kalit turlari, Om qonuni</li><li>Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (2-qism): AND/OR zanjirlari, multimetr, nosozlikni izlash, DIP switch → Arduino (2 bit)</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>LED holatini boshqarish dasturi</strong></td><td>Nomli konstantalar, <code>checkSwitch()</code> va <code>&amp;</code>, <code>delay()</code> siz <code>millis()</code> andozasi, heartbeat, <code>mode = (mode + 1) % 4</code> va <code>switch/case</code>, Serial&#39;ga faqat o&#39;zgarishda yozish</td><td>35 ball</td></tr><tr><td><strong>DIP switch zanjiri (1-qism)</strong></td><td>Zanjir qismlari, breadboard qatorlari, DIP ariqcha ustida, LED qutbi, Om qonuni bo&#39;yicha rezistor (5 V va 9 V), ikki mustaqil LED</td><td>30 ball</td></tr><tr><td><strong>Mantiq, o&#39;lchov va Arduino (2-qism)</strong></td><td>AND va OR sxemalari va haqiqat jadvallari, multimetr bilan kuchlanish/tok, rezistor tajribasi, nosozlikni izlash, <code>INPUT_PULLUP</code> bilan 2 bitli rejim tanlagichi</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>LED dasturi (35)</th><th>DIP zanjiri (30)</th><th>Mantiq va Arduino (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> <code>millis()</code> andozasini (<code>millis() - oxirgi &gt;= interval</code>) birinchi marta ko&#39;rganda o&#39;quvchilar ko&#39;pincha <code>oxirgi = millis()</code> qatorini unutadi — natijada blok har aylanishda bajariladi. Breadboardda eng ko&#39;p xato — komponent oyoqlarining bitta qatorga tushishi va DIP switch&#39;ning ariqcha ustiga qo&#39;yilmasligi.</li><li><strong>Tekshirish usuli:</strong> har bir o&#39;quvchidan tok yo&#39;lini barmoq bilan «yurib» ko&#39;rsatishni so&#39;rang (manba → kalit → rezistor → LED → GND). 9 V batareya ishlatilsa, rezistor kamida 470 Om ekanini nazorat qiling.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> uzoq bosish (long press) bilan rejimni nolga qaytarish, PWM bilan 4 darajali tungi chiroq, 4 pozitsiyali DIP switch&#39;dan 0–15 sonni o&#39;qish.</li></ul>',12))])])}const P=l(h,[["render",g]]);export{D as __pageData,P as default};
